public void itemStatusToTransferDependSites_New(Set _setWarehouse)
{
    METReqItemTableInventDimView metReqItemTableInventDimView, metReqItemTableInventDimViewIntComExists;

    while select metReqItemTableInventDimView
        exists join metReqItemTableInventDimViewIntComExists
        where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
        && metReqItemTableInventDimView.InventSiteId != metInventItemOrderSetup.SiteId
        && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
        && metReqItemTableInventDimView.RecId == metReqItemTableInventDimViewIntComExists.RecId
    {
        this.updateStatusToNew(METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetup.ItemId, metReqItemTableInventDimView.InventSiteId, true));
        METInventItemOrderSetup::updateChildItemSiteStatusToNew(metInventItemOrderSetup.ItemId, metReqItemTableInventDimView.InventSiteId);
    }

    //Intercompany case

    if(vendParameters)
    {
        changecompany(vendParameters.METInterCompanyLegalEntity)
        {
            METReqItemTableInventDimView metReqItemTableInventDimViewIntCom;

            while select InventSiteId, InventLocationId from metReqItemTableInventDimViewIntCom
                where metReqItemTableInventDimViewIntCom.ItemId == metInventItemOrderSetup.ItemId
                && metReqItemTableInventDimViewIntCom.ReqPOType == ReqPOType::Purch
                && metReqItemTableInventDimViewIntCom.VendGroup == vendParameters.METInterCompanyVendGroupId
            {
                if(_setWarehouse.in(metReqItemTableInventDimViewIntCom.VendIntercompanyWarehouse))
                {
                    this.updateStatusToNew(METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId, true));
                    METInventItemOrderSetup::updateChildItemSiteStatusToNew(metInventItemOrderSetup.ItemId, metReqItemTableInventDimViewIntCom.InventSiteId);
                }
            }
        }
    }

    /*
    while select metReqItemTableInventDimView
        where metReqItemTableInventDimView.ItemId == metInventItemOrderSetup.ItemId
        && metReqItemTableInventDimView.InventSiteId != metInventItemOrderSetup.SiteId
    {
        if(metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer && metReqItemTableInventDimView.InventSiteId == metReqItemTableInventDimView.MainWarehouseInventSiteId)
        {
            this.updateStatusToNew(METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetup.ItemId, metReqItemTableInventDimView.InventSiteId, true));
            METInventItemOrderSetup::updateChildItemSiteStatusToNew(metInventItemOrderSetup.ItemId, metReqItemTableInventDimView.InventSiteId);
        }
        else if(metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch && metReqItemTableInventDimView.VendGroup != vendParameters.METInterCompanyVendGroupId)
        {
            continue;
        }
        else if(metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch && metReqItemTableInventDimView.VendGroup == vendParameters.METInterCompanyVendGroupId)
        {
            changecompany(vendParameters.METInterCompanyLegalEntity)
            {
                METReqItemTableInventDimView metReqItemTableInventDimViewIntCom;

                while select metReqItemTableInventDimViewIntCom
                    where metReqItemTableInventDimViewIntCom.ItemId == metInventItemOrderSetup.ItemId
                    && metReqItemTableInventDimViewIntCom.InventSiteId == metReqItemTableInventDimViewIntCom.MainWarehouseInventSiteId
                {

                }
            }
        }
    }
    */

